insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A arguição de suspeição precederá a qualquer outra, salvo quando fundada em motivo superveniente.', '["A suspeição deve ser arguida antes de qualquer outra exceção.","Exceção: motivo superveniente."]'::jsonb, '["Antes de qualquer outra."]'::jsonb, 'A defesa arguiu a suspeição do juiz antes de qualquer outra exceção.', '["Assertiva que permite arguir a suspeição por último, sem exceção, erra."]'::jsonb, '[]'::jsonb, '["Art. 95","Art. 254"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-96'
