on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não aceitando a suspeição, o juiz mandará autuar em apartado a petição, dará sua resposta em três dias, podendo instruí-la e oferecer testemunhas, e determinará a remessa dos autos da exceção, em 24 horas, ao juiz ou tribunal competente para julgá-la. Reconhecida, preliminarmente, a relevância da arguição, o juiz ou tribunal, com citação das partes, marcará dia e hora para a inquirição das testemunhas, seguindo-se o julgamento, independentemente de mais alegações. Se a suspeição for de manifesta improcedência, o juiz ou relator a rejeitará liminarmente.', '["Juiz não aceita a suspeição: autua em apartado.","Resposta em três dias.","Remessa em 24 horas ao órgão competente para julgar.","§1º: relevância reconhecida: oitiva de testemunhas e julgamento.","§2º: manifesta improcedência: rejeição liminar."]'::jsonb, '["Prazos: três dias para a resposta e 24 horas para a remessa."]'::jsonb, 'Juiz recusa a suspeição, responde em três dias e remete a exceção ao tribunal.', '["Assertiva que fixa em cinco dias a resposta do juiz erra: são três dias."]'::jsonb, '[]'::jsonb, '["Art. 99","Art. 254"]'::jsonb, 'under_review', 'claude'
