insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No Supremo Tribunal Federal e nos Tribunais de Apelação, o juiz que se julgar suspeito declarará nos autos e, se for revisor, passará o feito ao substituto na ordem de precedência, ou, se for relator, apresentará os autos em mesa para nova distribuição. O juiz que não for relator nem revisor declara a suspeição verbalmente na sessão, registrando-se em ata. Se o presidente do tribunal se der por suspeito, caberá ao substituto designar dia para o julgamento e presidi-lo. Quanto à arguição pela parte, observam-se os arts. 98 a 101. Não reconhecida, a suspeição será julgada pelo tribunal pleno, funcionando como relator o presidente. Se o recusado for o presidente, o relator será o vice-presidente.', '["Suspeição de membro de tribunal: declaração nos autos.","Revisor: passa ao substituto; relator: nova distribuição.","Quem não é relator nem revisor declara verbalmente em ata.","Presidente suspeito: o substituto preside o julgamento.","Suspeição não reconhecida: tribunal pleno, relator o presidente.","Presidente recusado: relator o vice-presidente."]'::jsonb, '["Procedimento de suspeição nos tribunais."]'::jsonb, 'Desembargador relator se declara suspeito e os autos são redistribuídos.', '["Assertiva que mantém a relatoria com o juiz suspeito erra: os autos são redistribuídos."]'::jsonb, '[]'::jsonb, '["Art. 98","Art. 101"]'::jsonb, 'under_review', 'claude'
