insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A suspeição dos jurados deverá ser arguida oralmente, decidindo de plano o presidente do Tribunal do Júri, que a rejeitará se, negada pelo recusado, não for imediatamente comprovada, o que tudo constará da ata.', '["Suspeição de jurados é arguida oralmente.","Presidente do Júri decide de plano.","Rejeita se negada e não comprovada imediatamente.","Tudo consta da ata."]'::jsonb, '["Arguição oral e decisão imediata."]'::jsonb, 'A defesa argui oralmente a suspeição de um jurado, e o presidente decide na hora.', '["Assertiva que exige petição escrita para arguir a suspeição de jurados erra: é oral."]'::jsonb, '[]'::jsonb, '["Art. 448"]'::jsonb, 'under_review', 'claude'
