insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A exceção de incompetência do juízo pode ser oposta, verbalmente ou por escrito, no prazo de defesa. Se, ouvido o Ministério Público, for aceita a declinatória, o feito é remetido ao juízo competente, onde, ratificados os atos anteriores, o processo prossegue. Recusada a incompetência, o juiz continua no feito, fazendo tomar por termo a declinatória, se formulada verbalmente.', '["Exceção de incompetência: oral ou escrita, no prazo de defesa.","Aceita a declinatória: remessa ao juízo competente, com ratificação dos atos.","Recusada: o juiz continua e toma a declinatória por termo."]'::jsonb, '["Prazo: o de defesa.","A incompetência absoluta pode ser declarada a qualquer tempo."]'::jsonb, 'A defesa opõe, na resposta à acusação, exceção de incompetência territorial.', '["Assertiva que exige forma escrita para a exceção de incompetência erra: pode ser verbal."]'::jsonb, '[{"termo":"Declinatória","significado":"Alegação de que o juízo é incompetente."}]'::jsonb, '["Art. 109","Art. 110"]'::jsonb, 'under_review', 'claude'
