select u.id, u.content_sha256, 'Se em qualquer fase do processo o juiz reconhecer motivo que o torne incompetente, declará-lo-á nos autos, haja ou não alegação da parte, prosseguindo-se na forma do artigo anterior.', '["Juiz reconhece incompetência em qualquer fase.","Declara nos autos, com ou sem alegação da parte."]'::jsonb, '["Conhecimento de ofício da incompetência."]'::jsonb, 'Juiz percebe que o crime é da Justiça Federal e declina da competência.', '["Assertiva que exige alegação da parte para o juiz reconhecer a incompetência erra."]'::jsonb, '[]'::jsonb, '["Art. 108"]'::jsonb, 'under_review', 'claude'
