insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, o órgão do Ministério Público, os serventuários ou funcionários de justiça e os peritos ou intérpretes devem abster-se de servir no processo quando houver incompatibilidade ou impedimento legal, que declararão nos autos. Se não se der a abstenção, a incompatibilidade ou impedimento pode ser arguido pelas partes, seguindo-se o processo estabelecido para a exceção de suspeição.', '["Dever de abstenção diante de incompatibilidade ou impedimento legal.","Declaração nos autos.","Sem abstenção: arguição pelas partes pelo rito da suspeição."]'::jsonb, '["Impedimento e incompatibilidade seguem o rito da suspeição."]'::jsonb, 'O promotor impedido deve declarar o impedimento e deixar o processo.', '["Assertiva que cria rito distinto da suspeição para o impedimento erra: segue o da suspeição."]'::jsonb, '[]'::jsonb, '["Art. 252","Art. 253"]'::jsonb, 'under_review', 'claude'
