insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As questões atinentes à competência resolvem-se não só pela exceção própria, como também pelo conflito positivo ou negativo de jurisdição.', '["Competência pode ser discutida por exceção.","Também por conflito positivo ou negativo de jurisdição."]'::jsonb, '["Duas vias: exceção e conflito."]'::jsonb, 'Dois juízes se consideram competentes para o mesmo fato: conflito positivo.', '["Assertiva que restringe a discussão de competência à exceção erra: cabe também conflito."]'::jsonb, '[]'::jsonb, '["Art. 114"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-113'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Haverá conflito de jurisdição quando duas ou mais autoridades judiciárias se considerarem competentes ou incompetentes para conhecer do mesmo fato criminoso, ou quando surgir controvérsia entre elas sobre unidade de juízo, junção ou separação de processos.', '["Conflito positivo: ambos se consideram competentes.","Conflito negativo: ambos se consideram incompetentes.","Controvérsia sobre unidade de juízo, junção ou separação de processos."]'::jsonb, '["Conflito pode ser positivo ou negativo."]'::jsonb, 'Dois juízes declinam da competência para o mesmo crime: conflito negativo.', '["Assertiva que admite conflito de competência apenas quando ambos se declaram competentes erra."]'::jsonb, '[]'::jsonb, '["Art. 115"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-114'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O conflito poderá ser suscitado pela parte interessada, pelos órgãos do Ministério Público junto a qualquer dos juízos em dissídio, ou por qualquer dos juízes ou tribunais em causa.', '["Parte interessada.","Ministério Público junto a qualquer dos juízos.","Qualquer dos juízes ou tribunais em causa."]'::jsonb, '["Três legitimados."]'::jsonb, 'O juiz suscita conflito de competência com outro juízo.', '["Assertiva que nega legitimidade ao Ministério Público para suscitar o conflito erra."]'::jsonb, '[]'::jsonb, '["Art. 116"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-115'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os juízes e tribunais, sob a forma de representação, e a parte interessada, sob a de requerimento, darão parte escrita e circunstanciada do conflito, perante o tribunal competente, expondo os fundamentos e juntando os documentos comprobatórios. Quando negativo o conflito, juízes e tribunais podem suscitá-lo nos próprios autos. Se positivo, o relator pode determinar imediatamente que se suspenda o andamento do processo. O relator requisita informações às autoridades em conflito, no prazo marcado. Recebidas as informações e ouvido o procurador-geral, o conflito é decidido na primeira sessão, salvo diligência. Proferida a decisão, as cópias necessárias são remetidas às autoridades envolvidas.', '["Juízes: representação; parte: requerimento; ambos por escrito e circunstanciados.","Conflito negativo: pode ser suscitado nos próprios autos.","Conflito positivo: relator pode suspender o processo.","Informações das autoridades e parecer do procurador-geral.","Decisão na primeira sessão."]'::jsonb, '["Juiz suscita por REPRESENTAÇÃO; parte, por REQUERIMENTO."]'::jsonb, 'Juiz representa ao tribunal para decidir o conflito negativo.', '["Assertiva que exige que a parte suscite conflito por representação erra: é requerimento."]'::jsonb, '[]'::jsonb, '["Art. 115","Art. 117"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-116'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Supremo Tribunal Federal, mediante avocatória, restabelecerá a sua jurisdição sempre que exercida por qualquer dos juízes ou tribunais inferiores.', '["Avocatória do STF para restabelecer sua jurisdição usurpada."]'::jsonb, '["Instituto raro; hoje o meio usual é a reclamação ao STF."]'::jsonb, 'Juiz inferior julga causa de competência do STF: a avocatória restabelece a jurisdição.', '["Assertiva que atribui a avocatória ao Superior Tribunal de Justiça erra: o artigo menciona o STF."]'::jsonb, '[]'::jsonb, '["Art. 116"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-117'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Antes de transitar em julgado a sentença final, as coisas apreendidas não poderão ser restituídas enquanto interessarem ao processo.', '["Coisas apreendidas não são restituídas antes do trânsito, enquanto interessarem ao processo."]'::jsonb, '["Critério: interesse para o processo."]'::jsonb, 'A arma usada no crime fica apreendida até o fim do processo.', '["Assertiva que determina a restituição imediata das coisas apreendidas erra: elas ficam retidas enquanto interessarem ao processo."]'::jsonb, '[]'::jsonb, '["Art. 119","Art. 120"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-118'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As coisas a que se referem os arts. 74 e 100 do Código Penal não podem ser restituídas, mesmo depois de transitar em julgado a sentença final, salvo se pertencerem ao lesado ou a terceiro de boa-fé.', '["Instrumentos e produtos do crime perdidos em favor da União não são restituídos.","Exceção: pertencentes ao lesado ou a terceiro de boa-fé."]'::jsonb, '["Efeito da condenação: perda de instrumentos e produto do crime."]'::jsonb, 'Instrumento ilícito do crime não é devolvido ao autor após a condenação.', '["Assertiva que determina a restituição ao réu dos instrumentos do crime após o trânsito erra."]'::jsonb, '[]'::jsonb, '["Art. 118"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-119'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A restituição, quando cabível, pode ser ordenada pela autoridade policial ou pelo juiz, mediante termo nos autos, desde que não exista dúvida quanto ao direito do reclamante. Se duvidoso o direito, o pedido autua-se em apartado, com prazo de cinco dias para a prova ao requerente, e só o juiz criminal decide. Se as coisas forem apreendidas em poder de terceiro de boa-fé, o incidente é autuado em apartado e só a autoridade judicial o resolve, com intimação do terceiro, em prazo igual e sucessivo, e dois dias para arrazoar. Sempre será ouvido o Ministério Público. Em dúvida sobre o verdadeiro dono, o juiz remete as partes ao juízo cível e ordena o depósito. Coisas facilmente deterioráveis serão avaliadas e levadas a leilão, ou entregues ao terceiro idôneo mediante termo de responsabilidade.', '["Sem dúvida sobre o direito: restituição pela autoridade policial ou pelo juiz, mediante termo.","Direito duvidoso: autuação em apartado e prazo de cinco dias para a prova; só o juiz decide.","Coisa em poder de terceiro de boa-fé: só a autoridade judicial; prazo de dois dias para arrazoar.","Ministério Público sempre ouvido.","Dúvida sobre o dono: remessa ao juízo cível e depósito.","Coisas deterioráveis: avaliação e leilão ou entrega ao terceiro idôneo."]'::jsonb, '["A autoridade policial pode restituir apenas quando NÃO há dúvida."]'::jsonb, 'Veículo apreendido, sem dúvida sobre a propriedade, é restituído mediante termo.', '["Assertiva que permite à autoridade policial decidir restituição com direito duvidoso erra: só o juiz criminal."]'::jsonb, '[]'::jsonb, '["Art. 118","Art. 119"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-120'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

