select u.id, u.content_sha256, 'No caso de apreensão de coisa adquirida com os proventos da infração, aplica-se o disposto no art. 133 e seu parágrafo.', '["Bem adquirido com proventos da infração: aplica-se o art. 133 (avaliação e venda em leilão)."]'::jsonb, '["Remissão ao art. 133."]'::jsonb, 'Imóvel comprado com dinheiro do crime segue o procedimento de leilão do art. 133.', '["Assertiva que determina a restituição ao réu da coisa adquirida com os proventos do crime erra."]'::jsonb, '[]'::jsonb, '["Art. 133"]'::jsonb, 'under_review', 'claude'
