insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sem prejuízo do disposto no art. 120, as coisas apreendidas serão alienadas nos termos do art. 133 do Código. O parágrafo único foi revogado.', '["Coisas apreendidas são alienadas nos termos do art. 133.","Sem prejuízo da restituição do art. 120."]'::jsonb, '["Redação dada pela Lei nº 13.964, de 2019."]'::jsonb, 'Bem apreendido sem dono reclamante é alienado em leilão conforme o art. 133.', '["Assertiva que mantém o parágrafo único do art. 122 em vigor erra: foi revogado."]'::jsonb, '[]'::jsonb, '["Art. 120","Art. 133"]'::jsonb, 'under_review', 'claude'
