select u.id, u.content_sha256, 'Os instrumentos do crime, cuja perda em favor da União for decretada, e as coisas confiscadas nos termos do art. 100 do Código Penal serão inutilizados ou recolhidos a museu criminal, se houver interesse na sua conservação.', '["Instrumentos do crime perdidos em favor da União: inutilização ou museu criminal.","Museu somente se houver interesse na conservação."]'::jsonb, '["Destino dos instrumentos confiscados."]'::jsonb, 'Arma confiscada e sem interesse de conservação é inutilizada.', '["Assertiva que determina a venda em leilão dos instrumentos ilícitos do crime, nos termos do art. 124, erra."]'::jsonb, '[]'::jsonb, '["Art. 119"]'::jsonb, 'under_review', 'claude'
