select u.id, u.content_sha256, 'O sequestro autuar-se-á em apartado e admitirá embargos de terceiro.', '["Sequestro tramita em autos apartados.","Admite embargos de terceiro."]'::jsonb, '["Autos apartados."]'::jsonb, 'Terceiro de boa-fé opõe embargos contra o sequestro de seu imóvel.', '["Assertiva que veda embargos de terceiro contra o sequestro erra."]'::jsonb, '[]'::jsonb, '["Art. 130"]'::jsonb, 'under_review', 'claude'
